const digest=f=>createHash('sha256').update(fs.readFileSync(f)).digest('hex');
const indexPins=Object.fromEntries(fs.readdirSync(index,{recursive:true}).sort().filter(f=>fs.statSync(path.join(index,f)).isFile()).map(f=>[f,digest(path.join(index,f))]));
