  const norm=s=>String(s??'').replace(/\s+/gu,' ').trim();
  const name=e=>!e?.matches?null:e.matches('.cp-input')?'cp-input':e.matches('button[data-scope]')?'scope:'+e.dataset.scope:e.id||e.classList?.[0]||e.tagName;
  const href=e=>e?.hasAttribute('href')?new URL(e.href).pathname+new URL(e.href).hash:null;
  const time=()=>Math.round(performance.now());
  const box=e=>{
    if(!e)return null;
    const r=e.getBoundingClientRect(),x=r.x+r.width/2,y=r.y+r.height/2,top=document.elementFromPoint(x,y);
    return {top:Math.round(r.y*100)/100,center:[x,y],inView:r.width>0&&r.height>0&&x>=0&&x<innerWidth&&y>=0&&y<innerHeight,
      hit:e.contains(top),topNode:name(top)};
  };
  const point=s=>{const el=id(s);return el?{id:s,title:norm(el.textContent),...box(el)}:null;};
  function result(){
    const e=id(q('.cp-input')?.getAttribute('aria-activedescendant'));if(!e)return null;
    const a=id('cp-read-btn');
    return {id:e.id,role:e.getAttribute('role'),selected:e.getAttribute('aria-selected')==='true',
      label:norm(e.querySelector('.cp-item-title')?.textContent),group:norm(e.closest('.cp-group')?.querySelector('.cp-group-hd span')?.textContent),
      href:href(a),box:box(e),preview:box(a)};
  }
  const brief=()=>({doc:performance.timeOrigin,ageMs:time(),url:location.pathname+location.hash,history:history.length,
    focus:name(document.activeElement),scroll:Math.round(scrollY),match:q(':target')?.id??null});
  const ledger=[], scrolls=[];
  function read(){
    const b=brief(),toast=q('.gbs2-resume'),legacy=id('bookmarkToast'),sheet=id('partTocOverlay');
    const canonical=JSON.parse(localStorage.getItem(storage)??'null');
    return {...b, nav:performance.getEntriesByType('navigation').at(-1)?.type??null,h1:norm(q('h1')?.textContent),
      section:point(saveSection),explicit:point(linkSection),
      saved:canonical, readingLine:window.GBReaderState?.getReadingLine?.()??null,
      acknowledgements:Object.keys(sessionStorage).filter(k=>k.startsWith('gb:reader-resume-offered:v1:')).sort(),
      toast:toast?{on:toast.classList.contains('gbs2-on'),label:norm(toast.querySelector('span')?.textContent),role:toast.getAttribute('role'),go:box(toast.querySelector('.gbs2-resume-go'))}:null,
      legacy:legacy?{hidden:legacy.hidden,shown:legacy.classList.contains('show')}:null,
      bodyFixed:getComputedStyle(document.body).position==='fixed',locks:Object.keys(window.SiteUtils?._scrollLockSources||{}).sort(),
      palette:!!q('.cp-backdrop.is-open'),query:q('.cp-input')?.value??null,scope:q('.cp-scope-chip[aria-pressed="true"]')?.dataset.scope??null,
      result:result(),groups:[...document.querySelectorAll('.cp-item')].map(e=>e.getAttribute('aria-label')),pagefind:window.__pagefindReady__===true,
      toc:sheet?.classList.contains('is-open')??false,
      recordHistory:JSON.parse(localStorage.getItem('gb-cp-history')??'[]'),
      trace:{toast:ledger.slice(),scroll:scrolls.slice()},
      quiz:Object.fromEntries(['glsQuizQuestion','glsQuizVerdict','glsQuizExplanation','glsQuizSource'].map(k=>{
        const e=id(k);return [k,e?[norm(e.textContent),e.hidden,e.getAttribute('href')]:null];
      }))};
  }
  // Sample application-rendered offer state mutations. No interception or patching
  // of the timer, scroll code, restoreSnapshot, anchors, or handlers.
  let prev='absent';
