  addEventListener('scroll',()=>{scrolls.push([time(),Math.round(scrollY)]);if(scrolls.length>50)scrolls.shift();},{passive:true});
  for(const type of ['DOMContentLoaded','load','pageshow','hashchange'])addEventListener(type,e=>console.debug('GB_ENTRY_LIFE '+JSON.stringify({type,persisted:e.persisted??null,...brief()})));
  for(const type of ['click','keydown','wheel'])addEventListener(type,e=>{
    if(!e.target?.closest)return;
    let action,link=null,a=null;
    if(type==='wheel'&&location.pathname===dest)action='wheel';
    else if(type==='keydown'&&e.key==='Enter'&&e.target.id==='glsQuizSource'){action='review';link=href(e.target);}
    else if(type==='keydown'&&e.key==='Enter'&&e.target.matches('.cp-input')){action='exact-enter';a=result();link=a?.href;}
    else if(type==='click'){
      if(e.target.closest('#cp-read-btn')){action='exact-preview';a=result();link=href(e.target.closest('#cp-read-btn'));}
      else if(e.target.closest('.gbs2-resume-go'))action='restore';
      else if(location.pathname===from&&e.target.closest('a.gill-card__cta, #gbat-part-region-part2 a.gbat-sub')){
        action='native';link=href(e.target.closest('a'));
      }
    }
    if(action)console.debug('GB_ENTRY_ACT '+JSON.stringify({action,type,trusted:e.isTrusted,link,result:a,delta:e.deltaY??null,...brief()}));
  },{passive:true,capture:true});
